#!/bin/bash
# Antigravity ingestion: per-conversation SQLite databases (protobuf blobs in
# `steps` / `gen_metadata`) read by the built-in reader — WAL frames included,
# uncommitted ones ignored, overflow pages followed — priced per model with
# the reasoning suffix split into effort, plus the live state from
# conversation_summaries.db driving agentState and the Discord presence.
# Fixtures are generated by test/mocks/sqlite-fixture.js (no sqlite3 needed).
set -u
ROOT=$(cd "$(dirname "$0")/.." && pwd)
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
CL=$TMP/claude; PH=$TMP/pulse; AG=$TMP/antigravity
CID=0c0ffee0-1111-4222-8333-444455556666
mkdir -p "$CL/projects" "$PH" "$AG/conversations"
PORT=4961

FX=$TMP/fx.js
cat > "$FX" <<'EOF'
// node fx.js <AG> <CID> <ROOT> <conversation|summary> [status]
const fs = require('fs');
const [AG, CID, ROOT, what, status] = process.argv.slice(2);
const { writeDb, writeWal, buildImage, pb } = require(ROOT + '/test/mocks/sqlite-fixture.js');
const now = Date.now();
const created = (minAgo) => { const ms = now - minAgo * 60e3; return [[1, Math.floor(ms / 1000)], [2, (ms % 1000) * 1e6]]; };
if (what === 'summary') {
  const t = new Date(now - 30e3).toISOString().replace('T', ' ').replace('Z', '0000+00:00');
  const f = AG + '/conversation_summaries.db';
  fs.rmSync(f, { force: true });
  writeDb(f, [{ name: 'conversation_summaries',
    sql: 'CREATE TABLE `conversation_summaries` (`conversation_id` text,`title` text NOT NULL DEFAULT "",`last_modified_time` datetime NOT NULL,`workspace_uris` text NOT NULL,`status` text NOT NULL DEFAULT "")',
    rows: [[CID, 'demo', t, 'file:///c%3A/work/my%20proj', status]] }]);
  process.exit(0);
}
// usage: 1 enum, 2 uncached input, 3 output (incl. thinking), 5 cached,
// 9 thinking, 10 visible, 11 response id
const usageA = [[1, 1001], [2, 100000], [3, 50000], [5, 1000000], [9, 20000], [10, 30000], [11, 'resp-a']];
const usageB = [[1, 2002], [2, 200000], [3, 100000], [5, 500000]]; // no response id → joined by enum
const usageC = [[1, 3003], [2, 100000], [3, 100000], [11, 'resp-c']];
const usageD = [[1, 3003], [2, 9000000], [3, 9000000], [11, 'resp-d']];
const step = (minAgo, usage, pad) => [null, 1, pb([[1, created(minAgo)], ...(usage ? [[9, usage]] : []), ...(pad ? [[30, Buffer.alloc(pad, 7)]] : [])])];
const gen = (usage, name) => [null, pb([[1, [[4, usage], [19, name]]]])];
const STEPS = 'CREATE TABLE `steps` (`idx` integer PRIMARY KEY, `step_type` integer, `metadata` blob)';
const GENS = 'CREATE TABLE `gen_metadata` (`idx` integer PRIMARY KEY, `data` blob)';
const gens = [gen(usageA, 'claude-opus-5-5-high'), gen(usageB, 'gemini-3.1-pro-low'), gen(usageC, 'gemini-3.8-flash-n')];
const db = (steps) => [{ name: 'steps', sql: STEPS, rows: steps }, { name: 'gen_metadata', sql: GENS, rows: gens }];
const base = [step(6, null), step(5, usageA, 9000), step(4, usageB)]; // 9 kB pad → overflow chain
const f = AG + '/conversations/' + CID + '.db';
const img = writeDb(f, db(base));
// WAL: one committed transaction adding step C, then an UNCOMMITTED one adding D.
writeWal(f + '-wal', img, buildImage(db([...base, step(2, usageC)]), 4096),
  { uncommitted: buildImage(db([...base, step(2, usageC), step(1, usageD)]), 4096) });
// A junk "database" must not break the scan (unreadable → retried, never cached).
fs.writeFileSync(AG + '/conversations/deadbeef-0000-4000-8000-000000000000.db', 'not a database');
EOF
node "$FX" "$AG" "$CID" "$ROOT" conversation
node "$FX" "$AG" "$CID" "$ROOT" summary CASCADE_RUN_STATUS_RUNNING

case "$(uname -s)" in
  MINGW*|MSYS*|CYGWIN*) IPC='\\.\pipe\pulse-antigravity-'$$ ;;
  *) mkdir -p "$TMP/dipc"; IPC=$TMP/dipc/discord-ipc-0 ;;
esac
DLOG=$TMP/frames.log
node "$ROOT/test/mocks/mock-discord.js" "$IPC" "$DLOG" > /dev/null & MOCK=$!
sleep 0.5
echo '{"discordPresence": true, "discordClientId": "123456789012345678", "discordAntigravityImage": "https://x.test/ag.png"}' > "$PH/config.json"

PULSE_HOME=$PH CLAUDE_DIR=$CL CODEX_DIR=$TMP/no-codex GEMINI_DIR=$TMP/no-gemini ANTIGRAVITY_DIR=$AG \
PULSE_SUMMARY_MEMO_MS=0 PULSE_LIVE_STATE_MEMO_MS=0 \
PULSE_DISCORD_IPC="$IPC" PULSE_DISCORD_TICK_MS=300 PULSE_DISCORD_ROTATE_MS=600000 PULSE_DISCORD_STATE_HOLD_MS=0 \
node "$ROOT/server.js" --port $PORT --no-update-check >"$TMP/srv.log" 2>&1 &
SRV=$!
sleep 2.5
curl -s "http://127.0.0.1:$PORT/api/summary" > "$TMP/running.json"
echo "MARK running $(wc -l < "$DLOG")" > "$TMP/marks.txt"
# The run ends: only conversation_summaries.db changes, not the conversation.
node "$FX" "$AG" "$CID" "$ROOT" summary CASCADE_RUN_STATUS_IDLE
sleep 1.2
curl -s "http://127.0.0.1:$PORT/api/summary" > "$TMP/idle.json"
echo "MARK idle $(wc -l < "$DLOG")" >> "$TMP/marks.txt"
kill $SRV 2>/dev/null; wait $SRV 2>/dev/null
kill $MOCK 2>/dev/null

node -e '
const fs = require("fs");
const T = process.argv[1];
let fail = 0;
const ok = (c, m) => { console.log((c ? "PASS" : "FAIL") + "  " + m); if (!c) fail = 1; };
const near = (a, b) => typeof a === "number" && Math.abs(a - b) < 0.001;
const s = JSON.parse(fs.readFileSync(T + "/running.json", "utf8"));
const idle = JSON.parse(fs.readFileSync(T + "/idle.json", "utf8"));
ok((s.allSources || []).includes("antigravity"), "antigravity is a source (" + (s.allSources || []).join(",") + ")");
const per = (s.periods || []).find((p) => p.bySource && p.bySource.antigravity);
const bs = per ? per.bySource.antigravity : {}, bm = per ? per.byModel : {};
// A opus-5-5: 0.1M*4 + 0.05M*20 + 1M*4*0.05 = 1.60 · B gemini-3.1-pro: 0.2*2 + 0.1*12 + 0.5*0.2 = 1.70
// C gemini-3.8-flash-n (no public price → logged default 1.25/10): 0.1*1.25 + 0.1*10 = 1.125
ok(near(bs.cost, 4.425), "antigravity cost = 4.425 — committed WAL step counted, uncommitted one ignored (got " + bs.cost + ")");
ok(bs.tokens === 2150000, "antigravity tokens = 2.15M incl. cached input (got " + bs.tokens + ")");
ok(bs.messages === 3, "3 model calls — the user step without usage is skipped (got " + bs.messages + ")");
ok(bm["claude-opus-5-5"] && near(bm["claude-opus-5-5"].cost, 1.60), "-high suffix stripped: claude-opus-5-5 priced from its own row (1.60), across an overflow chain");
ok(bm["gemini-3.1-pro"] && near(bm["gemini-3.1-pro"].cost, 1.70), "-low suffix stripped; model joined by enum when the response id is missing (1.70)");
ok(bm["gemini-3.8-flash-n"] && near(bm["gemini-3.8-flash-n"].cost, 1.125), "codename model kept as-is at the default price (1.125)");
ok(!Object.keys(bm).some((m) => /-(high|low)$/.test(m)), "no model row keeps the effort suffix");
const log = fs.readFileSync(T + "/srv.log", "utf8");
ok(/unknown model "gemini-3\.8-flash-n"/.test(log), "the default-priced codename is logged");
ok(/2 antigravity/.test(log) && /unreadable/.test(log), "scan reports 2 antigravity files, the junk one unreadable (retried, not fatal)");
ok(s.agentState && s.agentState.provider === "antigravity" && s.agentState.state === "working",
  "RUNNING conversation → agentState antigravity:working (got " + JSON.stringify(s.agentState) + ")");
ok(s.activeNow && s.activeNow.provider === "antigravity" && s.activeNow.model === "gemini-3.8-flash-n",
  "activeNow follows the newest Antigravity call (got " + JSON.stringify(s.activeNow) + ")");
ok(idle.agentState && idle.agentState.provider === "antigravity" && idle.agentState.state === "idle",
  "status IDLE in conversation_summaries.db alone → idle, despite the cached conversation parse (got " + JSON.stringify(idle.agentState) + ")");
ok(s.discord && s.discord.images && s.discord.images.antigravity === "https://x.test/ag.png" && s.discord.images.defaults.antigravity === "pulse",
  "discord payload exposes the antigravity image slot (default: the idle art)");
const frames = fs.readFileSync(T + "/frames.log", "utf8").trim().split("\n").filter(Boolean).map(JSON.parse);
const marks = Object.fromEntries(fs.readFileSync(T + "/marks.txt", "utf8").trim().split("\n").map((l) => l.split(" ").slice(1)));
const lastAct = (n) => { for (let i = Math.min(Number(n), frames.length) - 1; i >= 0; i--) { const a = frames[i].payload && frames[i].payload.args && frames[i].payload.args.activity; if (a) return a; } return null; };
const a1 = lastAct(marks.running);
ok(a1 && a1.assets.large_image === "https://x.test/ag.png" && a1.assets.large_text === "Antigravity · working",
  "Discord while running: own image + \"Antigravity · working\" (got " + (a1 ? a1.assets.large_image + " | " + a1.assets.large_text : "none") + ")");
ok(a1 && /^Gemini 3\.8 Flash N/.test(a1.state || ""), "Discord second line names the model (got " + (a1 && a1.state) + ")");
const a2 = lastAct(marks.idle);
ok(a2 && a2.assets.large_text === "Using Antigravity", "Discord after the run: \"Using Antigravity\" (got " + (a2 && a2.assets.large_text) + ")");
process.exit(fail);
' "$TMP"
RES=$?
echo "---- exit $RES"
exit $RES
